   10. 终极气泡：3D 玻璃灰白 (双方统一高级质感)
   ================================================ */

div.chat-detail-screen .msg-bubble-wrapper {
  position: relative !important;
  overflow: visible !important;
  margin-bottom: 8px !important; 
}

div.chat-detail-screen .msg-content-stack {
  overflow: visible !important;
}

/* --- 1. 气泡本体：统一的玻璃灰底，极简高透 --- */
div.chat-detail-screen .bubble-them-custom,
div.chat-detail-screen .msg-plain-them,
div.chat-detail-screen .bubble-me-custom,
div.chat-detail-screen .msg-plain-me {
  border-radius: 20px !important;
  padding: 7px 12px !important;
  position: relative !important;
  overflow: visible !important;
  z-index: 1 !important; 
  background-image: none !important; 
  margin-bottom: 8px !important;
  background: linear-gradient(180deg, #ffffff 0%, #e2e5e9 100%) !important;
  color: #1a1a1a !important;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.9) !important;
  border: 1px solid #b8c0c8 !important;
  /* 增强的雕刻级 3D 阴影 */
  box-shadow: inset 0 6px 8px rgba(255, 255, 255, 1), 
              inset 0 -4px 6px rgba(0, 0, 0, 0.08),
              0 3px 6px rgba(0, 0, 0, 0.1) !important;
}

/* --- 2. 气泡高光团 --- */
div.chat-detail-screen .bubble-them-custom::before,
div.chat-detail-screen .msg-plain-them::before,
div.chat-detail-screen .bubble-me-custom::before,
div.chat-detail-screen .msg-plain-me::before {
  content: "" !important;
  position: absolute !important;
  top: 2px !important;  
  left: 5px !important; 
  right: 5px !important; 
  height: 14px !important; 
  border-radius: 18px 18px 6px 6px !important; 
  pointer-events: none !important;
  z-index: 2 !important; 
  border: none !important;
  box-shadow: none !important;
  /* 高亮反光点 */
  background: linear-gradient(180deg, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%) !important;
}

/* --- 3. 终极提亮水滴角 (绝对原汁原味，锁定 -0.5px) --- */
div.chat-detail-screen .bubble-them-custom::after,
div.chat-detail-screen .msg-plain-them::after {
  display: block !important;
  content: "" !important;
  position: absolute !important;
  top: 100% !important;     
  margin-top: -0.5px !important; /* 彻底还原到完美的 -0.5px */
  left: 4px !important;        
